"""Restaurant ops prototype: par-sheet supplier ordering + food-cost tracking."""
from dataclasses import dataclass, field

@dataclass
class Item:
    name: str
    unit_cost: float
    par: float      # target on-hand quantity
    on_hand: float

    def order_qty(self) -> float:
        return max(0.0, self.par - self.on_hand)

@dataclass
class Week:
    sales: float
    food_cost: float = 0.0

    def food_cost_pct(self) -> float:
        return 100.0 * self.food_cost / self.sales if self.sales else 0.0

def supplier_order(items):
    lines = [(i.name, i.order_qty(), round(i.order_qty() * i.unit_cost, 2)) for i in items if i.order_qty() > 0]
    return lines, round(sum(l[2] for l in lines), 2)

if __name__ == "__main__":
    items = [Item("Chicken thigh (lb)", 2.1, 40, 12), Item("Rice (lb)", 0.9, 50, 20), Item("Limes (ea)", 0.2, 60, 15)]
    lines, total = supplier_order(items)
    for name, qty, cost in lines:
        print(f"{name:20s} order {qty:6.1f}  ${cost:8.2f}")
    print("Order total:", total)
    w = Week(sales=8200.0, food_cost=2700.0)
    print("Food cost %:", round(w.food_cost_pct(), 1))
EOF
python3 ops.py && cat > README.md <<'EOF'
